(()=>{'use strict';const q=id=>document.getElementById(id);let ready=false,result=null,busy=false;async function check(){try{const r=await fetch('/api/jarvis/status',{cache:'no-store'});if(!r.ok)throw Error('Connection status unavailable');const d=await r.json();ready=!!d.ready;q('connection').textContent=ready?'Private AI connected · administrator workspace':'AI connection needs setup · existing business tools remain available';q('result-state').textContent=ready?'Ready. Your proposal will use the existing Jarvis backend.':'Configure your private AI connection from the existing designer dashboard.';}catch(e){q('connection').textContent=e.message;}q('run').disabled=!ready;}check();q('read-proposal').onclick=()=>{if(!result||!window.speechSynthesis)return;window.speechSynthesis.cancel();const voice=new SpeechSynthesisUtterance(String(result.answer||'').slice(0,16000));voice.lang='en-ZA';voice.onend=()=>q('voice-status').textContent='Readout complete.';voice.onerror=()=>q('voice-status').textContent='Voice readout unavailable on this device.';window.speechSynthesis.speak(voice);q('voice-status').textContent='Reading your AI proposal.';};q('stop-proposal').onclick=()=>{window.speechSynthesis?.cancel();q('voice-status').textContent='Voice stopped.';};window.addEventListener('pagehide',()=>window.speechSynthesis?.cancel());q('mission').addEventListener('submit',async e=>{e.preventDefault();if(!ready||busy)return;window.speechSynthesis?.cancel();q('read-proposal').disabled=true;busy=true;q('run').disabled=true;q('result').hidden=true;result=null;q('result-state').textContent='Preparing an evidence-based proposal…';try{const role=q('role').value;const r=await fetch('/api/jarvis/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({role,prompt:q('prompt').value,mode:['needs','research'].includes(role)?'research':'plan'}),signal:AbortSignal.timeout(90000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request could not be completed');result=d;q('read-proposal').disabled=!window.speechSynthesis;q('answer').textContent=d.answer;q('sources').replaceChildren();for(const s of d.sources||[]){let url;try{url=new URL(s.url);}catch{continue;}if(!['https:','http:'].includes(url.protocol))continue;const a=document.createElement('a');a.href=url.href;a.textContent=s.title||url.hostname;a.target='_blank';a.rel='noopener noreferrer';q('sources').append(a);}q('tasks').replaceChildren();for(const t of d.tasks||[]){const p=document.createElement('p');p.textContent=t.title+' — '+t.deliverable+' ('+t.module+')';q('tasks').append(p);}if(!(d.tasks||[]).length)q('tasks').textContent='No suggested tasks returned.';q('result').hidden=false;q('result-state').textContent='Proposal ready for administrator review. Suggested tasks have not been assigned.';}catch(e){q('result-state').textContent=e.message;}finally{busy=false;q('run').disabled=!ready;}});q('copy').onclick=async()=>{if(!result)return;const text=result.answer+'\n\n'+(result.tasks||[]).map(t=>t.title+': '+t.deliverable).join('\n')+'\n\n'+(result.sources||[]).map(s=>s.url).join('\n');try{await navigator.clipboard.writeText(text);q('result-state').textContent='Proposal copied.';}catch{q('result-state').textContent='Select the proposal text to copy it.';}};})();
